#!/usr/bin/env bash
# Creates a FAKE .env for the demo (random values, never real), and a git repo with the pre-commit hook.
set -euo pipefail
cd "$(dirname "$0")/.."

rand() { LC_ALL=C tr -dc 'A-Za-z0-9' </dev/urandom | head -c "$1"; }

cat > .env <<ENV
# FAKE values generated by scripts/setup-demo.sh for a live demo. Not real credentials.
DATABASE_URL=postgres://app:$(rand 20)@db.internal.example:5432/app
STRIPE_SECRET_KEY=sk_test_FAKE$(rand 24)
OPENAI_API_KEY=sk-proj-FAKE$(rand 40)
ENV
echo "Wrote fake .env"

if [ ! -d .git ]; then
  git init -q && git add -A && git -c user.name="${GIT_AUTHOR_NAME:-demo}" -c user.email="${GIT_AUTHOR_EMAIL:-demo@example.com}" commit -qm "demo: initial commit" && echo "Initialised git repo"
fi

if command -v pre-commit >/dev/null 2>&1; then
  pre-commit install && echo "Installed pre-commit hook (gitleaks)"
else
  echo "pre-commit not found: 'pipx install pre-commit' (or 'brew install pre-commit'), then 'pre-commit install'"
fi

# Optional: a demo-only env var so the postinstall demo has something to find in the environment
echo
echo "For demo 1, also run in your shell:  export DEMO_GITHUB_TOKEN=ghp_FAKE$(rand 32)"
